# ២. ឧទាហរណ៍ Binary Search (ទិន្នន័យត្រូវតែតម្រៀបរួច)
def binary_search(sorted_arr, target):
    left = 0
    right = len(sorted_arr) - 1

    while left <= right:
        mid = (left + right) // 2
        if sorted_arr[mid] == target:
            return mid
        elif sorted_arr[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return -1

sorted_nums = [10, 20, 30, 40, 50, 60, 70]
